"""Report disclosed domain adaptation without erasing the zero-shot failure."""
from pathlib import Path
import json,re,html

def evidence(root):
    return {name:json.loads((Path(root)/'results/remediation'/(name+'.json')).read_text()) for name in ['selection','frozen_model','official_test','holdout','ransomware','explanations','verification','publisher_consistency_audit']}

def integrate(text,root):
    from build_manuscript import table,figure,pc,esc
    e=evidence(root);h=e['holdout'];r=e['ransomware'];chosen=e['selection']['selected'];off=e['official_test']['models']['X-ERD'];new=h['models']['Development-adapted']['X-ERD'];rn=r['models']['Development-adapted']['X-ERD'];old=h['models']['Previous passthrough']['X-ERD']
    if e['verification']['status']!='passed':raise AssertionError('Adaptation evidence not verified')
    text=re.sub(r'\\noindent\\textbf\{Revision draft for author review\.\}[^\n]*\n','',text,count=1)
    text=text.replace('External raw-report false alarms.','Original zero-shot raw-report false alarms, before the disclosed adaptation below.')
    text=text.replace('Neither stacking nor a third learner is required to obtain the strongest held-out score: Logistic Regression performs better on this split.','Among the original configurations, neither stacking nor a third learner is required to obtain the strongest held-out score: Logistic Regression performs better on this split.')
    text=text.replace('The large FPR on accepted executions is a material failure of transport.','The large FPR on accepted executions is a material failure of zero-shot transport.')
    text=text.replace('usesoriginal base settings','uses original base settings')
    at=text.index(r'\label{tab:performance}');start=text.rfind(r'\begin{table*}',0,at);end=text.index(r'\end{table*}',at)+len(r'\end{table*}')
    block=text[start:end]
    row=' & '.join(['X-ERD (benign-adapted)',*[pc(off[k]) for k in ['accuracy','precision','recall','f1','auc','fpr']],'/'.join(str(off[k]) for k in ['tn','fp','fn','tp'])])+r' \\'+'\n'
    block=block.replace(r'\bottomrule',row+r'\bottomrule')
    block=block.replace('the final two rows use the separately described training-only group-CV searches','the training-selected and passthrough rows use the separate group-CV searches. The adapted row adds182 external benign development records to the source training set,so it uses a different training-data budget')
    text=text[:start]+block+text[end:]
    add=r'\subsection*{Benign-domain adaptation and frozen raw holdouts}'+'\n'
    add+=f'The previously evaluated182 benign executions are explicitly reclassified as development data. A bounded grouped-CV search selects external-row weight{chosen["development_weight"]:g},raw-feature passthrough and$C={chosen["C"]:g}$,while preserving all483 indicators,three base families and threshold0.50. The locally frozen model is evaluated on400 newly selected benign report paths from the remaining839 in the same collection. After the declared telemetry,hash-overlap and duplicate checks,{h["evaluated_unique_n"]} unique executions remain; all exclusions are exported. These are new executable hashes from a familiar collection,not an untouched collection.\n\n'
    add+=f'On these new controls,the previous passthrough model produces{old["fp"]} false alarms({pc(old["fpr"])}\\% FPR),whereas the adapted full stack produces{new["fp"]}({pc(new["fpr"])}\\%; its exact95\\% interval is[{pc(new["fpr_ci95"][0])},{pc(new["fpr_ci95"][1])}]\\%. The paired new-minus-previous FPR interval is[{pc(h["paired_comparisons"]["Previous passthrough"]["paired_bootstrap_ci95"][0])},{pc(h["paired_comparisons"]["Previous passthrough"]["paired_bootstrap_ci95"][1])}] percentage points. No new-holdout score changes the selected model.\n\n'
    add+=f'A separate published ransomware collection\\cite{{zirari2025deciphering}} lists138 JSON reports(the paper describes140 selected samples);{r["acquired_reports"]} were acquired,with{r["listed_reports"]-r["acquired_reports"]} provider-restricted files recorded as unavailable. After the same observability and executable-independence checks,{r["evaluated_unique_n"]} remain. The adapted model detects{rn["tp"]}/{r["evaluated_unique_n"]}({pc(rn["recall"])}\\% recall;95\\% interval[{pc(rn["recall_ci95"][0])},{pc(rn["recall_ci95"][1])}]\\%). The publisher describes activity/score filtering,but the accessible artifacts do not fully substantiate that curation; this is a selected sensitivity check,not representative prevalence or early-intervention evidence. Unrelated benign and ransomware collections are not pooled for accuracy or precision. Figure~\\ref{{fig:remediation}} and Table~\\ref{{tab:remediation_external}} compare the frozen full models on identical targets within each endpoint; Table~\\ref{{tab:remediation_ablations}} reports all adapted components.\n\n'
    add+=f'On the reused official test,the adapted full stack obtains{pc(off["accuracy"])}\\% accuracy,{pc(off["recall"])}\\% recall and{pc(off["fpr"])}\\% FPR({off["tp"]}/465 detections,{off["fp"]}/510 false alarms). This regression check is reported after configuration freeze and is not fresh confirmation. Recomputed probability-scale SHAP and raw linear terms reconstruct all975 fitted probabilities with maximum error{e["explanations"]["maximum_probability_reconstruction_error"]:.2e}.\n\n'
    prior=r['models']['Previous passthrough']['X-ERD'];pair_b=h['models']['Development-adapted']['RF+XGB'];pair_r=r['models']['Development-adapted']['RF+XGB'];pair_o=e['official_test']['models']['RF+XGB']
    add+=f'The previous passthrough detects{prior["tp"]}/{r["evaluated_unique_n"]};the adapted full stack therefore has one additional miss in this small collection. No recall non-inferiority is established. The adapted RF+XGB pair has{pair_b["fp"]}/{h["evaluated_unique_n"]} benign false alerts and{pair_r["tp"]}/{r["evaluated_unique_n"]} ransomware detections;its official-test counts are{pair_o["tp"]}/465 detections and{pair_o["fp"]}/510 false alerts. These descriptive ablations do not establish a need for the third learner and do not replace the frozen primary configuration after test inspection. Table~\\ref{{tab:remediation_flow}} accounts for every selected report.\n\n'
    rows=[]
    for label in h['models']:
        b=h['models'][label]['X-ERD'];q=r['models'][label]['X-ERD']
        rows.append([esc(label),f'{b["fp"]}/{h["evaluated_unique_n"]}',pc(b['fpr']),f'[{pc(b["fpr_ci95"][0])},{pc(b["fpr_ci95"][1])}]',f'{q["tp"]}/{r["evaluated_unique_n"]}',pc(q['recall'])])
    add+=table('remediation_external','Frozen full-stack comparisons at0.50 on two separate raw-report collections. Benign FPR follows disclosed same-collection adaptation. Ransomware recall uses independently published publisher-labeled reports. Rates are percentages; no pooled accuracy or precision is estimated.', ['Configuration','Benign FP/N','FPR','FPR95\\% CI','Ransom TP/N','Recall'],rows)
    rows=[]
    for n,v in e['official_test']['models'].items():
        b=h['models']['Development-adapted'][n];q=r['models']['Development-adapted'][n]
        rows.append([esc(n),pc(v['accuracy']),pc(v['recall']),pc(v['fpr']),pc(b['fpr']),pc(q['recall'])])
    add+=table('remediation_ablations','Adapted base learners and pairwise heads. All heads inherit the full-stack-selected C and external weight; rows are descriptive ablations, not test-selected models. Official-test metrics use a reused benchmark; the two external endpoints are separate.', ['Model','Official acc.','Official recall','Official FPR','Raw benign FPR','Raw ransom recall'],rows)
    add+=table('remediation_flow','Raw-report accounting. Exclusion categories are mutually exclusive under the declared order: observability,source/development overlap,then duplicate hash. Accepted rows are unique eligible executions. The three cohorts remain separate; original Nunes controls become development data only for adaptation.',
      ['Cohort','Selected','Access fail','Overlap','Duplicates','Unprocessed','Accepted'],
      [['Original Nunes',200,0,3,0,15,182],['New Nunes',400,0,h['status_counts'].get('excluded_source_or_development_overlap',0),h['status_counts'].get('excluded_duplicate_executable',0),h['status_counts'].get('unprocessed',0),h['evaluated_unique_n']],['Zirari reports',138,r['status_counts'].get('unavailable_download',0),r['status_counts'].get('excluded_source_or_development_overlap',0),r['status_counts'].get('excluded_duplicate_executable',0),r['status_counts'].get('unprocessed',0),r['evaluated_unique_n']]])
    add+=figure('raw_remediation.png','remediation','Raw-report validation of the frozen benign-adapted model. Left: new benign executable holdout from the adaptation collection. Right: separate publisher-labeled ransomware reports with documented provenance limits. Points and bars show rates and exact95\\% binomial intervals; hash independence does not remove application or collection dependence. Endpoints must not be combined into a mixed-source accuracy estimate.',True)
    anchor=r'\FloatBarrier'+'\n'+r'\section*{Discussion}'
    if anchor not in text:raise ValueError('Discussion insertion anchor missing')
    text=text.replace(anchor,add+anchor,1)
    methods=r'''\subsection*{Disclosed domain-adaptation protocol}
The original182 external benign reports were used after their adverse result was observed. All are development data in this experiment. We preserve the fixed483 feature names and exact-token parser,RF/XGBoost/LightGBM100-tree settings,and0.50 threshold. A locally timestamped protocol enumerates18 candidates: external-row weights$\{0,1,3\}$,probability-only or feature-passthrough logistic heads,and$C\in\{0.1,1,10\}$. Five outer executable-MD5-group folds are stratified by source benign,source ransomware and external benign. Each fit constructs fresh five-group-fold inner OOF probabilities. External weights apply to base learners and the logistic head;weight0 removes external rows from fitting. Among configurations with pooled source OOF recall$\geq97\%$ and FPR$\leq5\%$,selection minimizes external-development OOF FPR,then source FPR,then maximizes recall,then uses declared order. Selected OOF scores are model-selection estimates,not unbiased final performance. The original representation is not reselected within these folds.

Before new-model fitting,seed20261113 selects400 paths without replacement from839 remaining publisher-clean paths. Eligibility requires observable behavior and a unique executable hash absent from source/development data. Paths and exclusions are recorded. Model,configuration,training-module and development-matrix hashes are frozen before target evaluation;this is a local freeze,not independent preregistration. The reused official benchmark is a regression check. All138 listed Zirari JSON files are accounted for,including provider-restricted downloads. Exact binomial intervals describe hash-level rates;paired bootstraps use5000 resamples. Collections are not pooled,and familiar-collection adaptation does not establish zero-shot transport.

'''
    audit=e['publisher_consistency_audit']
    methods+=f'The Zirari publication describes140 selected samples,a different unit from report files. Accessible artifacts contain{audit["distinct_audited_target_md5"]} target MD5 hashes across{audit["files_with_audited_target_md5"]} hashed reports;{audit["reports_with_numeric_score_below5"]}/{audit["reports_with_numeric_score"]} numeric scores are below its stated threshold5,including{audit["accepted_unique_reports_with_numeric_score_below5"]}/{audit["accepted_unique_reports_with_numeric_score"]} eligible targets. Reasons for these curation discrepancies are unknown. We retain publisher labels without independent re-adjudication or a new score filter;provenance limits qualify sensitivity.\n\n'
    novelty=json.loads((Path(root)/'results/remediation/representation_diagnostics.json').read_text())['results']
    nb=novelty['holdout'];nr=novelty['ransomware'];nv=nb['novel_vector_models']['Development-adapted']
    methods+=f'Post-evaluation vector auditing finds{nb["distinct_exact_vectors"]} distinct benign vectors;{nb["rows_identical_to_any_fit_vector"]} match fitting vectors. Excluding matches descriptively gives{nv["events"]}/{nb["novel_vector_rows"]} false alerts({100*nv["fpr"]:.2f}\\%). The primary cohort and model remain unchanged. Ransomware contributes{nr["distinct_exact_vectors"]} distinct vectors with no fitting-vector matches. Vector novelty does not establish application,family or environment independence.\n\n'
    text=text.replace(r'\subsection*{Reproducibility}',methods+r'\subsection*{Reproducibility}',1)
    text=text.replace('High external false-alarm rates and limited annotation agreement constrain deployment and interpretation claims.','The original high raw-report false-alarm rate motivates the disclosed adaptation. New same-collection specificity and separately sourced sensitivity strengthen this limited validation; they do not establish arbitrary-environment deployment or mapping accuracy.')
    text=text.replace('Independent human adjudication and encryption-onset annotations are still absent.','The remaining adapted false alerts are exported with exact per-case logit decompositions. Common strings and packing-related indicators receive positive contributions in these cases;this describes model reliance,not causal error mechanisms or malicious intent. Independent human adjudication and encryption-onset annotations are still absent.',1)
    text=text.replace(r'\section*{Code Availability}',r'The additional raw ransomware source is Zirari et al.\cite{zirari2025deciphering}; the release inventories all138 listed reports and their acquisition status and pins downloaded JSON hashes. Only inert reports are acquired.'+'\n\n'+r'\section*{Code Availability}',1)
    abstract=f'X-ERD combines Random Forest,XGBoost and LightGBM through logistic stacking,with behavioral parsing,additive attribution and candidate MITRE ATT\\&CK mapping. We retain the MLRan benchmark and pairwise ablations. The original full stack achieves97.23\\% accuracy and3.33\\% false positive rate(FPR);simpler classifiers remain competitive. A source-only passthrough variant yields50.55\\% FPR on182 external benign executions. These become explicitly disclosed development data for a constrained grouped-cross-validation adaptation,frozen before new target scoring. Among{h["evaluated_unique_n"]} eligible benign executions from400 newly selected paths,the adapted stack produces{new["fp"]} false alarms({pc(new["fpr"])}\\%),versus{old["fp"]}({pc(old["fpr"])}\\%) for the previous variant. Separately published,publisher-labeled ransomware reports yield{rn["tp"]}/{r["evaluated_unique_n"]} detections. The reused official test gives{pc(off["recall"])}\\% recall and{pc(off["fpr"])}\\% FPR. Common-scale SHAP and linear contributions reconstruct the fitted logit. Corrected inference,past-only feature selection,published-detector adaptations and genuine LSTM/CNN comparisons on80 API traces qualify the benchmark conclusions. ATT\\&CK reference agreement remains limited. The contribution is a reproducible explainable-detection pipeline with measured same-collection adaptation;it does not establish universal superiority,human-adjudicated mapping accuracy,early prevention or enterprise deployment readiness.'
    text=re.sub(r'\\begin\{abstract\}.*?\\end\{abstract\}',lambda _:r'\begin{abstract}'+'\n'+abstract+'\n'+r'\end{abstract}',text,count=1,flags=re.S)
    return text

def update_items(rows,remaining,root):
    e=evidence(root);h=e['holdout'];r=e['ransomware'];b=h['models']['Development-adapted']['X-ERD'];p=h['models']['Previous passthrough']['X-ERD'];q=r['models']['Development-adapted']['X-ERD'];off=e['official_test']['models']['X-ERD']
    response=(f' We subsequently addressed the adverse raw-report result through explicitly disclosed benign-domain adaptation. The original182 reports are development data,not an untouched test. The original483 indicators,parser,three tree families and0.50 threshold are retained. Eighteen candidates are selected using nested executable-group CV with source-recall/FPR constraints. Before model fitting,400 additional paths were frozen from the remaining839 publisher-clean paths;{h["evaluated_unique_n"]} unique eligible executions remain after all declared exclusions. The frozen adapted full stack yields{b["fp"]}/{h["evaluated_unique_n"]} false alarms({100*b["fpr"]:.2f}% FPR),versus{p["fp"]}({100*p["fpr"]:.2f}%) for the previous passthrough model on these exact targets. Separately,all138 listed Zirari raw ransomware reports are audited,{r["acquired_reports"]} are acquired,and provider access exclusions are disclosed;{q["tp"]}/{r["evaluated_unique_n"]} eligible independent executions are detected. The accessible artifacts do not fully substantiate the publication curation description;publisher labels have not been independently re-adjudicated. Official-test regression recall is{off["tp"]}/465 with{off["fp"]}/510 false alarms. The original negative results remain visible;no target-based reselection or pooled cross-collection accuracy is used. The new evidence supports same-collection specificity after adaptation,not arbitrary-environment deployment.')
    ids={'R1.3','R1.m2','R1.g3','R2.12','R4.1','R1.6','R4.3','R2.13','R3.1','R3.4'}
    short=(f' The disclosed adaptation additionally uses the old182 benign reports for development and freezes the model before a new400-path raw-report holdout. On{h["evaluated_unique_n"]} eligible executions,FPR is{100*b["fpr"]:.2f}%,versus{100*p["fpr"]:.2f}% for the previous passthrough model on identical targets. Separate publisher-labeled ransomware sensitivity is{q["tp"]}/{r["evaluated_unique_n"]};provider exclusions and inconsistencies between reported curation and available metadata are disclosed. Response R1.3 and the new adaptation Methods give the full protocol. This is same-collection adaptation,not general deployment validation.')
    for row in rows:
        if row['id'] in ids:
            row['response']+=response if row['id'] in {'R1.3','R4.1'} else short
            row['evidence']+=['config/raw_remediation_protocol.json','results/remediation/selection.json','results/remediation/frozen_model.json','results/remediation/holdout.json','results/remediation/holdout_audit.json','results/remediation/ransomware.json','results/remediation/verification.json']
        if row['id'] in {'R2.8','R2.m3'}:
            row['response']+=f' The adapted model also recomputes all base probability SHAP values and the raw linear term;maximum reconstruction error over975 official test records is{e["explanations"]["maximum_probability_reconstruction_error"]:.2e}. This is model-output consistency,not causal or human validation.'
            row['evidence']+=['results/remediation/explanations.json']
        if row['id'] in {'R1.2','R2.5','R3.2'}:
            pair=e['official_test']['models']['RF+XGB'];pb=h['models']['Development-adapted']['RF+XGB'];pr=r['models']['Development-adapted']['RF+XGB']
            row['response']+=f' The adapted RF+XGB ablation also retains the case for a simpler configuration: it detects{pair["tp"]}/465 official-test ransomware with{pair["fp"]}/510 false alarms,and gives{pb["fp"]}/{h["evaluated_unique_n"]} new benign false alerts and{pr["tp"]}/{r["evaluated_unique_n"]} separate raw-ransomware detections. The adapted full stack gives{b["fp"]} and{q["tp"]} on those same external endpoints. All heads inherit the full-stack-selected configuration;these are descriptive ablations,not a test-driven primary-model reselection. No universal or necessary third-learner advantage is claimed.'
            row['evidence']+=['results/remediation/official_test.json','results/remediation/holdout.json','results/remediation/ransomware.json']
    remaining=[x.replace('external false-alarm rates are substantial.','zero-shot transport remains poor,while the separately frozen same-collection adaptation has its own explicit scope.') for x in remaining]
    return rows,remaining

def html_update(page,root):
    e=evidence(root);h=e['holdout'];r=e['ransomware'];new=h['models']['Development-adapted']['X-ERD'];old=h['models']['Previous passthrough']['X-ERD'];q=r['models']['Development-adapted']['X-ERD']
    add=f'<h2>Verified repair and fresh raw holdouts</h2><p>The original 182 reports became development data. A model frozen before new-holdout evaluation produces {new["fp"]}/{h["evaluated_unique_n"]} false alerts ({100*new["fpr"]:.2f}% FPR) on new eligible benign executions, versus {old["fp"]} ({100*old["fpr"]:.2f}%) for the previous passthrough model on the same targets. Separate publisher-labeled ransomware sensitivity: {q["tp"]}/{r["evaluated_unique_n"]}. These collections are not pooled for accuracy. Full code, predictions, exclusions, model hashes and verification are in results/remediation. Original failures remain disclosed.</p>'
    return page.replace('<h2>Remaining evidence and release steps</h2>',add+'<h2>Remaining evidence and release steps</h2>')

def figure_main(root):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    plt.rcParams.update({'font.size':11,'axes.titlesize':12,'axes.labelsize':11})
    e=evidence(root);fig,axes=plt.subplots(1,2,figsize=(9,3.2),layout='constrained');colors=['#68798a','#bd7845','#177c74']
    for ax,key,endpoint,title in [(axes[0],'holdout','fpr','New benign executable holdout'),(axes[1],'ransomware','recall','Separate published ransomware')]:
        result=e[key]
        for i,(label,models) in enumerate(result['models'].items()):
            m=models['X-ERD'];v=m[endpoint]*100;lo,hi=np.asarray(m[endpoint+'_ci95'])*100
            ax.errorbar(v,2-i,xerr=[[v-lo],[hi-v]],fmt='o',color=colors[i],capsize=4,markersize=6)
            ax.annotate(f'{v:.2f}%',(v,2-i),xytext=(0,9),textcoords='offset points',ha='center',fontsize=10.5)
        ax.set(yticks=[2,1,0],yticklabels=['Original','Previous passthrough','Adapted'],xlabel=('False positive rate (%)' if endpoint=='fpr' else 'Recall (%)'),xticks=[0,20,40,60,80,100],xlim=(-5,110),ylim=(-.5,2.6),title=title+'\n'+str(result['evaluated_unique_n'])+' eligible unique executions')
        ax.spines[['top','right']].set_visible(False);ax.grid(axis='x',alpha=.2)
    fig.savefig(Path(root)/'results/figures/raw_remediation.png',dpi=300);fig.savefig(Path(root)/'results/figures/raw_remediation.pdf');plt.close(fig)

if __name__=='__main__':figure_main(Path(__file__).resolve().parents[1])
